func Enrich(next func(context.Context, Order) error, src CustomerSource) func(context.Context, Order) error {
    var g singleflight.Group
    return func(ctx context.Context, o Order) error {
        v, err, _ := g.Do(o.CustomerID, func() (any, error) { return src.Find(ctx, o.CustomerID) })
        if err != nil { return err }        // or degrade: continue with the bare order
        if c, ok := v.(Customer); ok { o.Name, o.Region = c.Name, c.Region }
        return next(ctx, o)
    }
}
